class Solution {
  private static long linear(long[] a, int k) {
    long NEG = Long.MIN_VALUE / 4;
    int n = a.length;
    long[][] dp = new long[k + 1][4];
    for (long[] row : dp) java.util.Arrays.fill(row, NEG);
    dp[0][3] = 0;
    for (long x : a) {
      long[][] nd = new long[k + 1][4];
      for (long[] row : nd) java.util.Arrays.fill(row, NEG);
      for (int j = 0; j <= k; j++) {
        for (int mask = 0; mask < 4; mask++) {
          long v = dp[j][mask];
          if (v == NEG) continue;
          // continue the current segment (or the virtual complete segment) with optional picks
          if (j > 0) relax(nd[j], mask, v, x);
          // start a new segment after a complete one
          if (mask == 3 && j < k) relax(nd[j + 1], 0, v, x);
        }
      }
      dp = nd;
    }
    long best = 0;
    for (int j = 1; j <= k; j++) best = Math.max(best, dp[j][3]);
    return best;
  }

  private static void relax(long[] row, int mask, long v, long x) {
    row[mask] = Math.max(row[mask], v);
    if ((mask & 1) == 0) row[mask | 1] = Math.max(row[mask | 1], v + x);
    if ((mask & 2) == 0) row[mask | 2] = Math.max(row[mask | 2], v - x);
    if (mask == 0) row[3] = Math.max(row[3], v);
  }

  public long maximumScore(int[] nums, int k) {
    int n = nums.length, maxIdx = 0;
    for (int i = 1; i < n; i++) if (nums[i] > nums[maxIdx]) maxIdx = i;
    long[] first = new long[n], last = new long[n];
    for (int i = 0; i < n; i++) {
      first[i] = nums[(maxIdx + i) % n];
      last[i] = nums[(maxIdx + 1 + i) % n];
    }
    return Math.max(linear(first, k), linear(last, k));
  }
}
